1	//! Workflow-level display contract.
2	//!
3	//! Owns the run header, persistent progress bar (pinned at the bottom),
4	//! and the run summary. Delegates per-step rendering to
5	//! [`super::StepDisplay`].
6	//!
7	//! ## Construction
8	//!
9	//! - Interactive runs: [`TerminalWorkflowDisplay::new`] with an
10	//!   [`Arc<TerminalSurface>`] and [`OutputMode`].
11	//! - CI / non-interactive: [`NonInteractiveWorkflowDisplay::new`].
12	
13	use std::sync::Arc;
14	use std::time::Duration;
15	
16	use indicatif::{ProgressBar, ProgressStyle};
17	
18	use crate::ui::progress::format_duration;
19	use crate::ui::surface::{PinnedBar, TerminalSurface};
20	use crate::ui::theme::BivvyTheme;
21	use crate::ui::OutputMode;
22	
23	use super::step::{NonInteractiveStepDisplay, StepDisplay, TerminalStepDisplay};
24	use super::{RunHeader, RunSummary};
25	
26	/// Workflow-level display contract.
27	///
28	/// Implementations own the workflow's pinned progress bar (if any) and
29	/// produce per-step displays via [`Self::begin_step`].
30	pub trait WorkflowDisplay {
31	    /// Show the rich run header at the top of a run.
32	    fn show_run_header(&mut self, hdr: &RunHeader);
33	
34	    /// Initialize the persistent progress bar.
35	    ///
36	    /// Called once before the step loop. Implementations that don't
37	    /// support a pinned bar (CI mode, silent mode) make this a no-op.
38	    fn start_progress(&mut self, total: usize);
39	
40	    /// Update the progress bar.
41	    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration);
42	
43	    /// Finish and clear the progress bar before the summary is rendered.
44	    fn finish_progress(&mut self);
45	
46	    /// Show a run summary at the end of a run.
47	    fn show_run_summary(&mut self, summary: &RunSummary);
48	
49	    /// Hand off to the step layer.
50	    ///
51	    /// The returned [`StepDisplay`] shares only the surface (or output
52	    /// stream) with the workflow — never any draw state.
53	    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay>;
54	
55	    /// Print a status line above the pinned region (used for filter
56	    /// reasons, dry-run notes, etc.).
57	    fn message(&mut self, msg: &str);
58	
59	    /// Print a hint (post-run guidance) above the pinned region.
60	    fn hint(&mut self, hint: &str);
61	}
