63	// ────────────────────────── Interactive impl ──────────────────────────
64	
65	/// Interactive workflow display backed by a [`TerminalSurface`].
66	pub struct TerminalWorkflowDisplay {
67	    surface: Arc<TerminalSurface>,
68	    theme: BivvyTheme,
69	    mode: OutputMode,
70	    pinned: Option<PinnedBar>,
71	}
72	
73	impl TerminalWorkflowDisplay {
74	    /// Construct a new terminal workflow display.
75	    pub fn new(surface: Arc<TerminalSurface>, mode: OutputMode) -> Self {
76	        let theme = if crate::ui::should_use_colors() {
77	            BivvyTheme::new()
78	        } else {
79	            BivvyTheme::plain()
80	        };
81	        Self {
82	            surface,
83	            theme,
84	            mode,
85	            pinned: None,
86	        }
87	    }
88	
89	    /// Format the bar message string with bracket bar + counts.
90	    fn format_bar(theme: &BivvyTheme, current: usize, total: usize, elapsed: Duration) -> String {
91	        let filled = if total > 0 { (current * 16) / total } else { 0 };
92	        let empty = 16usize.saturating_sub(filled);
93	        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
94	        format!(
95	            "\n{} {}/{} steps {} {}",
96	            theme.info.apply_to(format!("[{}]", bar)),
97	            current,
98	            total,
99	            theme.dim.apply_to("·"),
100	            theme
101	                .duration
102	                .apply_to(format!("{} elapsed", format_duration(elapsed))),
103	        )
104	    }
105	}
106	
107	impl WorkflowDisplay for TerminalWorkflowDisplay {
108	    fn show_run_header(&mut self, hdr: &RunHeader) {
109	        if !self.mode.shows_status() {
110	            return;
111	        }
112	        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
113	        self.surface.println(&format!(
114	            "\n{} {} {} {} {} {} {}\n",
115	            self.theme.header.apply_to("⛺"),
116	            self.theme.highlight.apply_to(&hdr.app_name),
117	            self.theme.dim.apply_to(format!("v{}", hdr.version)),
118	            self.theme.dim.apply_to("·"),
119	            self.theme
120	                .dim
121	                .apply_to(format!("{} workflow", hdr.workflow)),
122	            self.theme
123	                .dim
124	                .apply_to(format!("· {} {}", hdr.step_count, step_label)),
125	            self.theme.dim.apply_to(format!("· env: {}", hdr.env_name)),
126	        ));
127	    }
128	
129	    fn start_progress(&mut self, total: usize) {
130	        if !self.mode.shows_status() {
131	            return;
132	        }
133	        let bar = ProgressBar::new(total as u64);
134	        bar.set_style(ProgressStyle::default_bar().template("{msg}").unwrap());
135	        bar.set_message(Self::format_bar(&self.theme, 0, total, Duration::ZERO));
136	        self.pinned = Some(self.surface.pin_bottom(bar));
137	    }
138	
139	    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
140	        if !self.mode.shows_status() {
141	            return;
142	        }
143	        if let Some(p) = &self.pinned {
144	            p.set_message(Self::format_bar(&self.theme, current, total, elapsed));
145	        }
146	    }
147	
148	    fn finish_progress(&mut self) {
149	        // Drop clears the bar.
150	        self.pinned = None;
151	    }
152	
153	    fn show_run_summary(&mut self, summary: &RunSummary) {
154	        if !self.mode.shows_status() {
155	            return;
156	        }
157	
158	        let b = &self.theme.border;
159	        let mut lines = vec![
160	            String::new(),
161	            format!(
162	                "{} {}",
163	                b.apply_to("┌─"),
164	                b.apply_to("Summary ──────────────────────────")
165	            ),
166	        ];
167	
168	        for step in &summary.step_results {
169	            let icon = step.status.styled(&self.theme);
170	            let duration_str = step.duration.map(format_duration).unwrap_or_default();
171	            let detail_str = step.detail.as_deref().unwrap_or("");
172	
173	            let right_side = if !duration_str.is_empty() {
174	                self.theme.duration.apply_to(duration_str).to_string()
175	            } else if !detail_str.is_empty() {
176	                self.theme.dim.apply_to(detail_str).to_string()
177	            } else {
178	                String::new()
179	            };
180	
181	            lines.push(format!(
182	                "{} {} {:<20} {}",
183	                b.apply_to("│"),
184	                icon,
185	                step.name,
186	                right_side,
187	            ));
188	        }
189	
190	        let satisfied_part = if summary.steps_satisfied > 0 {
191	            format!(
192	                " {} {} already satisfied",
193	                self.theme.dim.apply_to("·"),
194	                summary.steps_satisfied,
195	            )
196	        } else {
197	            String::new()
198	        };
199	        lines.push(
200	            b.apply_to("├────────────────────────────────────")
201	                .to_string(),
202	        );
203	        lines.push(format!(
204	            "{} Total: {} {} {} run {} {} skipped{}",
205	            b.apply_to("│"),
206	            self.theme
207	                .duration
208	                .apply_to(format_duration(summary.total_duration)),
209	            self.theme.dim.apply_to("·"),
210	            summary.steps_run,
211	            self.theme.dim.apply_to("·"),
212	            summary.steps_skipped,
213	            satisfied_part,
214	        ));
215	        lines.push(
216	            b.apply_to("└────────────────────────────────────")
217	                .to_string(),
218	        );
219	
220	        for line in &lines {
221	            self.surface.println(line);
222	        }
223	    }
224	
225	    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
226	        Box::new(TerminalStepDisplay::new(
227	            Arc::clone(&self.surface),
228	            self.mode,
229	            index,
230	            total,
231	        ))
232	    }
233	
234	    fn message(&mut self, msg: &str) {
235	        if self.mode.shows_status() {
236	            self.surface.println(msg);
237	        }
238	    }
239	
240	    fn hint(&mut self, hint: &str) {
241	        if !self.mode.shows_status() {
242	            return;
243	        }
244	        self.surface
245	            .println(&self.theme.hint.apply_to(hint).to_string());
246	        self.surface.println("");
247	    }
248	}
