252	/// Non-interactive (CI / headless) workflow display.
253	///
254	/// Prints structured lines to stdout/stderr; skips the pinned progress
255	/// bar entirely.
256	pub struct NonInteractiveWorkflowDisplay {
257	    mode: OutputMode,
258	    is_ci: bool,
259	}
260	
261	impl NonInteractiveWorkflowDisplay {
262	    /// Construct a new non-interactive workflow display.
263	    pub fn new(mode: OutputMode) -> Self {
264	        Self {
265	            mode,
266	            is_ci: crate::shell::is_ci(),
267	        }
268	    }
269	
270	    /// Construct a non-interactive workflow display with an explicit CI
271	    /// flag (test override).
