277	impl WorkflowDisplay for NonInteractiveWorkflowDisplay {
278	    fn show_run_header(&mut self, hdr: &RunHeader) {
279	        if !self.mode.shows_status() {
280	            return;
281	        }
282	        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
283	        println!(
284	            "\n⛺ {} v{} · {} workflow · {} {} · env: {}\n",
285	            hdr.app_name, hdr.version, hdr.workflow, hdr.step_count, step_label, hdr.env_name,
286	        );
287	    }
288	
289	    fn start_progress(&mut self, _total: usize) {}
290	
291	    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
292	        if self.is_ci {
293	            return;
294	        }
295	        if !self.mode.shows_status() {
296	            return;
297	        }
298	        let filled = if total > 0 { (current * 16) / total } else { 0 };
299	        let empty = 16usize.saturating_sub(filled);
300	        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
301	        println!(
302	            "  [{}] {}/{} steps · {} elapsed",
303	            bar,
304	            current,
305	            total,
306	            format_duration(elapsed),
307	        );
308	    }
309	
310	    fn finish_progress(&mut self) {}
311	
312	    fn show_run_summary(&mut self, summary: &RunSummary) {
313	        if !self.mode.shows_status() {
314	            return;
315	        }
316	
317	        println!();
318	        println!("  ┌─ Summary ──────────────────────────");
319	
320	        for step in &summary.step_results {
321	            let icon = step.status.icon();
322	            let duration_str = step.duration.map(format_duration).unwrap_or_default();
323	            let detail_str = step.detail.as_deref().unwrap_or("");
324	
325	            let right_side = if !duration_str.is_empty() {
326	                duration_str
327	            } else if !detail_str.is_empty() {
328	                detail_str.to_string()
329	            } else {
330	                String::new()
331	            };
332	
333	            println!("  │ {} {:<20} {}", icon, step.name, right_side);
334	        }
335	
336	        println!("  ├────────────────────────────────────");
337	        let satisfied_part = if summary.steps_satisfied > 0 {
338	            format!(" · {} already satisfied", summary.steps_satisfied)
339	        } else {
340	            String::new()
341	        };
342	        println!(
343	            "  │ Total: {} · {} run · {} skipped{}",
344	            format_duration(summary.total_duration),
345	            summary.steps_run,
346	            summary.steps_skipped,
347	            satisfied_part,
348	        );
349	        println!("  └────────────────────────────────────");
350	        // No trailing "Setup complete!" / "Setup failed" line — see the
351	        // matching note in `TerminalWorkflowDisplay::show_run_summary`.
352	    }
353	
354	    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
355	        Box::new(NonInteractiveStepDisplay::new(self.mode, index, total))
356	    }
357	
358	    fn message(&mut self, msg: &str) {
359	        if self.mode.shows_status() {
360	            println!("{}", msg);
361	        }
362	    }
363	
364	    fn hint(&mut self, hint: &str) {
365	        if self.mode.shows_status() {
366	            println!("  💡 {}", hint);
367	        }
368	    }
369	}
