376	/// Shared buffer between [`MockWorkflowDisplay`] and the
377	/// [`MockStepDisplay`]s it spawns. Tests can read this through the
378	/// workflow display to assert on every captured interaction.
379	#[derive(Default)]
380	pub struct MockState {
381	    /// Run headers shown.
382	    pub headers: Vec<RunHeader>,
383	    /// Run summaries shown.
384	    pub summaries: Vec<RunSummary>,
385	    /// Workflow progress events (current, total, elapsed).
386	    pub progress_events: Vec<(usize, usize, Duration)>,
387	    /// Workflow-level messages (above the progress region).
388	    pub workflow_messages: Vec<String>,
389	    /// Workflow-level hints.
390	    pub workflow_hints: Vec<String>,
391	    /// Per-step messages captured from `MockStepDisplay`.
392	    pub step_messages: Vec<String>,
393	    /// Per-step warnings.
394	    pub step_warnings: Vec<String>,
395	    /// Per-step error blocks (command, output, hint, indent).
396	    pub step_error_blocks: Vec<(String, String, Option<String>, usize)>,
397	    /// Per-step success lines (formatted).
398	    pub step_successes: Vec<String>,
399	    /// Per-step error lines (formatted).
400	    pub step_errors: Vec<String>,
401	    /// Per-step skipped lines (formatted).
402	    pub step_skipped: Vec<String>,
403	}
