405	/// In-memory workflow display for tests.
406	///
407	/// Captures every interaction (workflow- and step-level) so assertions
408	/// can be made without depending on stdout capture.
409	pub struct MockWorkflowDisplay {
410	    state: Rc<RefCell<MockState>>,
411	}
412	
413	impl Default for MockWorkflowDisplay {
414	    fn default() -> Self {
415	        Self::new()
416	    }
417	}
418	
419	impl MockWorkflowDisplay {
420	    /// Construct a new mock workflow display.
421	    pub fn new() -> Self {
422	        Self {
423	            state: Rc::new(RefCell::new(MockState::default())),
424	        }
425	    }
426	
427	    /// Borrow the captured state for assertions.
428	    pub fn state(&self) -> std::cell::Ref<'_, MockState> {
429	        self.state.borrow()
430	    }
431	
432	    /// Whether any captured message contains `needle`. Searches across
433	    /// workflow- and step-level messages.
434	    pub fn has_message(&self, needle: &str) -> bool {
435	        let s = self.state.borrow();
436	        s.workflow_messages.iter().any(|m| m.contains(needle))
437	            || s.step_messages.iter().any(|m| m.contains(needle))
438	    }
439	
440	    /// Whether any captured success line contains `needle`.
441	    pub fn has_success(&self, needle: &str) -> bool {
442	        let s = self.state.borrow();
443	        s.step_successes.iter().any(|m| m.contains(needle))
444	    }
445	
446	    /// Whether any captured error contains `needle`.
447	    pub fn has_error(&self, needle: &str) -> bool {
448	        let s = self.state.borrow();
449	        s.step_errors.iter().any(|m| m.contains(needle))
450	    }
451	
452	    /// Whether any captured warning contains `needle`.
453	    pub fn has_warning(&self, needle: &str) -> bool {
454	        let s = self.state.borrow();
455	        s.step_warnings.iter().any(|m| m.contains(needle))
456	    }
457	
458	    /// All captured run headers.
459	    pub fn headers(&self) -> Vec<RunHeader> {
460	        self.state.borrow().headers.clone()
461	    }
462	
463	    /// All captured run summaries.
464	    pub fn summaries(&self) -> Vec<RunSummary> {
465	        self.state.borrow().summaries.clone()
466	    }
467	}
