515	impl MockStepDisplay {
516	    /// Construct a new mock step display sharing state with its
517	    /// parent [`MockWorkflowDisplay`].
518	    pub fn new(state: Rc<RefCell<MockState>>, index: usize, total: usize) -> Self {
519	        let step_number = format!("[{}/{}]", index + 1, total);
520	        let step_indent = step_number.chars().count() + 1;
