556	impl crate::ui::Prompter for MockStepDisplay {
557	    fn prompt(
558	        &mut self,
559	        prompt: &crate::ui::Prompt,
560	    ) -> crate::error::Result<crate::ui::PromptResult> {
561	        // Default mock prompt: use the prompt's default value if
562	        // provided, otherwise return a blank result. Real test mocks
563	        // pass through MockUI / dialog stubs.
564	        let is_multiselect = matches!(
565	            prompt.prompt_type,
566	            crate::ui::PromptType::MultiSelect { .. }
567	        );
568	        if let Some(default) = &prompt.default {
569	            if is_multiselect {
570	                let values: Vec<String> =
571	                    default.split(',').map(|s| s.trim().to_string()).collect();
572	                return Ok(crate::ui::PromptResult::Strings(values));
573	            }
574	            return Ok(crate::ui::PromptResult::String(default.clone()));
575	        }
576	        Ok(crate::ui::PromptResult::String(String::new()))
577	    }
578	}
