580	impl super::step::StepDisplay for MockStepDisplay {
581	    fn show_step_header(&mut self, step_name: &str, _title: Option<&str>) {
582	        self.state
583	            .borrow_mut()
584	            .step_messages
585	            .push(format!("{} {}", self.step_number, step_name));
586	    }
587	
588	    fn start_running(&mut self, command: &str) {
589	        self.state
590	            .borrow_mut()
591	            .step_messages
592	            .push(format!("Running `{}`...", command));
593	    }
594	
595	    fn update_live_output(&mut self, _line: crate::shell::OutputLine) {}
596	
597	    fn finish(
598	        &mut self,
599	        status: crate::steps::StepStatus,
600	        duration: Option<Duration>,
601	        _detail: Option<&str>,
602	    ) {
603	        let label = status.label();
604	        let body = match duration {
605	            Some(d) => format!("{} ({})", label, crate::ui::format_duration(d)),
606	            None => label.to_string(),
607	        };
608	        let mut state = self.state.borrow_mut();
609	        match status {
610	            crate::steps::StepStatus::Completed => state.step_successes.push(body),
611	            crate::steps::StepStatus::Failed => state.step_errors.push(body),
612	            crate::steps::StepStatus::Skipped => state.step_skipped.push(body),
613	            _ => state.step_messages.push(body),
614	        }
615	    }
616	
617	    fn finish_and_clear(&mut self) {}
618	
619	    fn output_mode(&self) -> OutputMode {
620	        OutputMode::Normal
621	    }
622	
623	    fn step_indent(&self) -> usize {
624	        self.step_indent
625	    }
626	
627	    fn step_number(&self) -> &str {
628	        &self.step_number
629	    }
630	
631	    fn is_interactive(&self) -> bool {
632	        false
633	    }
634	}
