42	/// Per-step display contract.
43	///
44	/// Extends [`OutputWriter`] and [`Prompter`] so the step display is
45	/// drop-in compatible with code paths that expect those traits
46	/// (recovery menu, gap installer). Implementors must ensure that
47	/// calling any `finish_*` method cleanly closes the transient region
48	/// before returning.
49	pub trait StepDisplay: OutputWriter + Prompter {
50	    /// Write the step header line into scrollback.
51	    fn show_step_header(&mut self, step_name: &str, title: Option<&str>);
52	
53	    /// Mount the transient region with a spinner.
54	    ///
55	    /// The `command` is normalized to a single line (newlines collapsed
56	    /// to spaces, truncated). The transient region reserves room for
57	    /// the live-output tail.
58	    fn start_running(&mut self, command: &str);
59	
60	    /// Append a line of live command output to the spinner's tail.
61	    ///
62	    /// No-op if the transient region has not been mounted.
63	    fn update_live_output(&mut self, line: OutputLine);
64	
65	    /// Finalize the step. Clears the transient region and prints the
66	    /// final result line into scrollback. The label and icon are
67	    /// derived from `status` (via [`StepStatus::label`] and
68	    /// [`StepStatus::display_char`]) so the displayed text is always
69	    /// in lockstep with the actual step outcome.
70	    ///
71	    /// Optional `duration` is shown in parentheses after the label;
72	    /// optional `detail` is appended dimmed.
73	    fn finish(&mut self, status: StepStatus, duration: Option<Duration>, detail: Option<&str>);
74	
75	    /// Finalize the step without writing a final line — used when the
76	    /// caller will write its own final state afterwards (auto-satisfied
77	    /// step, blocked dependency, etc.).
78	    fn finish_and_clear(&mut self);
79	
80	    /// The output mode currently in effect.
81	    fn output_mode(&self) -> OutputMode;
82	
83	    /// Width (in columns) at which content should be indented to align
84	    /// under the step name. `step_indent() == step_number().chars().count() + 1`.
85	    fn step_indent(&self) -> usize;
86	
87	    /// The step number string, e.g. `[1/3]`.
88	    fn step_number(&self) -> &str;
89	
90	    /// Whether the underlying surface supports interactive prompts.
91	    fn is_interactive(&self) -> bool;
92	
93	    /// Build an [`OutputCallback`] that feeds command output into the
94	    /// transient region's live-output tail. Returns `None` if the
95	    /// display has no live-output concept (silent / non-interactive
96	    /// non-verbose).
97	    fn live_output_callback(&mut self) -> Option<crate::shell::OutputCallback> {
98	        None
99	    }
100	}
