104	const RING_BUFFER_VERBOSE: usize = 3;
105	const RING_BUFFER_NORMAL: usize = 2;
106	/// Cap on a single line of live output before truncation.
107	const MAX_OUTPUT_LINE_LEN: usize = 72;
108	
109	/// How many tail lines to ring-buffer for the given output mode.
110	fn live_tail_capacity(mode: OutputMode) -> usize {
111	    match mode {
112	        OutputMode::Verbose => RING_BUFFER_VERBOSE,
113	        OutputMode::Normal => RING_BUFFER_NORMAL,
114	        _ => 0,
115	    }
116	}
