118	/// Interactive per-step display backed by a [`TerminalSurface`].
119	pub struct TerminalStepDisplay {
120	    surface: Arc<TerminalSurface>,
121	    theme: BivvyTheme,
122	    mode: OutputMode,
123	    step_number: String,
124	    step_indent: usize,
125	    region: Option<TransientRegion>,
126	    /// Ring-buffer of recent live-output lines for the spinner tail.
127	    tail: VecDeque<String>,
128	    /// Spinner base message — preserved so live-output updates don't
129	    /// drop the "Running ..." prefix.
130	    base_message: String,
131	    /// Maximum tail capacity (depends on output mode).
132	    tail_capacity: usize,
133	}
