135	impl TerminalStepDisplay {
136	    /// Construct a new terminal step display.
137	    pub fn new(
138	        surface: Arc<TerminalSurface>,
139	        mode: OutputMode,
140	        index: usize,
141	        total: usize,
142	    ) -> Self {
143	        let theme = if crate::ui::should_use_colors() {
144	            BivvyTheme::new()
145	        } else {
146	            BivvyTheme::plain()
147	        };
148	        let step_number = format!("[{}/{}]", index + 1, total);
149	        let step_indent = step_number.chars().count() + 1;
150	        Self {
151	            surface,
152	            theme,
153	            mode,
154	            step_number,
155	            step_indent,
156	            region: None,
157	            tail: VecDeque::new(),
158	            base_message: String::new(),
159	            tail_capacity: live_tail_capacity(mode),
160	        }
161	    }
162	
163	    /// Collapse a multi-line command into a single line.
164	    fn normalize_command(command: &str) -> String {
165	        let collapsed = command
166	            .lines()
167	            .map(|l| l.trim())
168	            .filter(|l| !l.is_empty())
169	            .collect::<Vec<_>>()
170	            .join("; ");
171	        if collapsed.chars().count() > 96 {
172	            let mut out: String = collapsed.chars().take(93).collect();
173	            out.push_str("...");
174	            out
175	        } else {
176	            collapsed
177	        }
178	    }
179	
180	    /// Truncate a single output line for display in the tail.
181	    fn truncate_line(line: &str) -> String {
182	        let trimmed = line.trim_end();
183	        if trimmed.chars().count() > MAX_OUTPUT_LINE_LEN {
184	            let mut out: String = trimmed
185	                .chars()
186	                .take(MAX_OUTPUT_LINE_LEN.saturating_sub(3))
187	                .collect();
188	            out.push_str("...");
189	            out
190	        } else {
191	            trimmed.to_string()
192	        }
193	    }
194	
195	    /// Render the spinner message: base + tail buffer (already truncated).
196	    fn render_message(&self) -> String {
197	        let prefix = " ".repeat(self.step_indent.saturating_add(2));
198	        let mut msg = self.base_message.clone();
199	        for line in &self.tail {
200	            msg.push('\n');
201	            msg.push_str(&prefix);
202	            msg.push_str(&self.theme.dim.apply_to(format!("» {}", line)).to_string());
203	        }
204	        msg
205	    }
206	}
