242	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
243	        let b = &self.theme.border;
244	        let pad = " ".repeat(indent);
245	        let mut lines = vec![
246	            format!(
247	                "{}{} {}",
248	                pad,
249	                b.apply_to("┌─"),
250	                b.apply_to("Command ──────────────────────────")
251	            ),
252	            format!(
253	                "{}{} {}",
254	                pad,
255	                b.apply_to("│"),
256	                self.theme.command.apply_to(command)
257	            ),
258	        ];
259	
260	        if !output.is_empty() {
261	            lines.push(format!(
262	                "{}{} {}",
263	                pad,
264	                b.apply_to("├─"),
265	                b.apply_to("Output ───────────────────────────")
266	            ));
267	            for line in output.lines() {
268	                lines.push(format!("{}{} {}", pad, b.apply_to("│"), line));
269	            }
270	        }
271	
272	        lines.push(format!(
273	            "{}{}",
274	            pad,
275	            b.apply_to("└────────────────────────────────────")
276	        ));
277	
278	        if let Some(h) = hint {
279	            lines.push(String::new());
280	            lines.push(format!(
281	                "{}{} {}",
282	                pad,
283	                self.theme.hint.apply_to("Hint:"),
284	                self.theme.hint.apply_to(h)
285	            ));
286	        }
287	
288	        for line in &lines {
289	            self.surface.println(line);
290	        }
291	    }
