307	impl StepDisplay for TerminalStepDisplay {
308	    fn show_step_header(&mut self, step_name: &str, title: Option<&str>) {
309	        if !self.mode.shows_status() {
310	            return;
311	        }
312	        let header = format!(
313	            "{} {}",
314	            self.theme.step_number.apply_to(&self.step_number),
315	            self.theme.step_title.apply_to(step_name)
316	        );
317	        let line = match title {
318	            Some(t) if t != step_name => format!(
319	                "{} {} {}",
320	                header,
321	                self.theme.dim.apply_to("—"),
322	                self.theme.dim.apply_to(t)
323	            ),
324	            _ => header,
325	        };
326	        self.surface.println(&line);
327	    }
328	
329	    fn start_running(&mut self, command: &str) {
330	        if !self.mode.shows_spinners() {
331	            return;
332	        }
333	        let collapsed = Self::normalize_command(command);
334	        let prefix = " ".repeat(self.step_indent);
335	        self.base_message = format!("Running `{}`...", collapsed);
336	
337	        let bar = ProgressBar::new_spinner();
338	        bar.set_style(
339	            ProgressStyle::default_spinner()
340	                .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
341	                .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
342	                .unwrap(),
343	        );
344	        bar.set_message(self.base_message.clone());
345	        bar.enable_steady_tick(Duration::from_millis(80));
346	
347	        // Reserve max_lines = 1 (spinner row) + tail_capacity.
348	        let max_lines = 1 + self.tail_capacity;
349	        let region = self.surface.transient_above_pinned(bar, max_lines);
350	        self.tail.clear();
351	        self.region = Some(region);
352	    }
353	
354	    fn update_live_output(&mut self, line: OutputLine) {
355	        if self.tail_capacity == 0 || self.region.is_none() {
356	            return;
357	        }
358	        let raw = match &line {
359	            OutputLine::Stdout(s) | OutputLine::Stderr(s) => s.clone(),
360	        };
361	        let trimmed = raw.trim_end();
362	        if trimmed.is_empty() {
363	            return;
364	        }
365	        let display = Self::truncate_line(trimmed);
366	        self.tail.push_back(display);
367	        while self.tail.len() > self.tail_capacity {
368	            self.tail.pop_front();
369	        }
370	        let msg = self.render_message();
371	        if let Some(region) = &self.region {
372	            region.set_message(&msg);
373	        }
374	    }
375	
376	    fn finish(&mut self, status: StepStatus, duration: Option<Duration>, detail: Option<&str>) {
377	        // Drop the region first so the line is cleared before we print.
378	        self.region = None;
379	        if !self.mode.shows_status() && !matches!(status, StepStatus::Failed) {
380	            // Failed lines still emit (errors are never silent), but
381	            // success/skipped honor silent mode.
382	            return;
383	        }
384	
385	        // Build "Label" or "Label (Xms)" from the status enum — the
386	        // sole source of truth for what gets printed on the result row.
387	        let label = status.label();
388	        let body = match duration {
389	            Some(d) => format!("{} ({})", label, format_duration(d)),
390	            None => label.to_string(),
391	        };
392	
393	        // Icon + label colored to match the status. The icon comes
394	        // from the status enum (`display_char`) — not from
395	        // `theme.format_success` etc., which bake in their own icons
396	        // and would emit "✓ ✓ Completed" / "✗ ✗ Failed" if combined.
397	        let icon_body = format!("{} {}", status.display_char(), body);
398	        let styled_body: String = match status {
399	            StepStatus::Completed => self.theme.success.apply_to(icon_body).to_string(),
400	            StepStatus::Failed => self.theme.error.apply_to(icon_body).to_string(),
401	            StepStatus::Skipped => self.theme.dim.apply_to(icon_body).to_string(),
402	            StepStatus::Pending | StepStatus::Running => {
403	                self.theme.dim.apply_to(icon_body).to_string()
404	            }
405	        };
406	
407	        let pad = " ".repeat(self.step_indent);
408	        let detail_str = detail
409	            .map(|d| format!(" {}", self.theme.dim.apply_to(format!("— {}", d))))
410	            .unwrap_or_default();
411	
412	        self.surface
413	            .println(&format!("{}{}{}", pad, styled_body, detail_str));
414	    }
415	
416	    fn finish_and_clear(&mut self) {
417	        self.region = None;
418	    }
419	
420	    fn output_mode(&self) -> OutputMode {
421	        self.mode
422	    }
423	
424	    fn step_indent(&self) -> usize {
425	        self.step_indent
426	    }
427	
428	    fn step_number(&self) -> &str {
429	        &self.step_number
430	    }
431	
432	    fn is_interactive(&self) -> bool {
433	        true
434	    }
435	
436	    fn live_output_callback(&mut self) -> Option<crate::shell::OutputCallback> {
437	        // Reuse the existing spinner-based ring buffer in spinner.rs —
438	        // it operates on a cloned ProgressBar with no &mut self required.
439	        if self.tail_capacity == 0 {
440	            return None;
441	        }
442	        let bar = self.region.as_ref()?.bar_clone()?;
443	        let max_lines = self.tail_capacity;
444	        let indent = self.step_indent.saturating_add(2);
445	        Some(crate::ui::spinner::live_output_callback(
446	            bar,
447	            self.base_message.clone(),
448	            indent,
449	            max_lines,
450	        ))
451	    }
452	}
