568	        let collapsed = TerminalStepDisplay::normalize_command(command);
569	        let prefix = " ".repeat(self.step_indent);
570	        println!("{}Running `{}`...", prefix, collapsed);
571	    }
572	
573	    fn update_live_output(&mut self, line: OutputLine) {
574	        if !matches!(self.mode, OutputMode::Verbose) {
575	            return;
576	        }
577	        match line {
578	            OutputLine::Stdout(s) => print!("{}", s),
579	            OutputLine::Stderr(s) => eprint!("{}", s),
580	        }
581	    }
582	
583	    fn finish(&mut self, status: StepStatus, duration: Option<Duration>, detail: Option<&str>) {
584	        if !self.mode.shows_status() && !matches!(status, StepStatus::Failed) {
585	            return;
586	        }
587	        let label = status.label();
588	        let body = match duration {
589	            Some(d) => format!("{} ({})", label, format_duration(d)),
590	            None => label.to_string(),
591	        };
592	        let detail_str = detail.map(|d| format!(" — {}", d)).unwrap_or_default();
593	        let pad = " ".repeat(self.step_indent);
594	        let line = format!("{}{} {}{}", pad, status.display_char(), body, detail_str);
595	        if matches!(status, StepStatus::Failed) {
596	            eprintln!("{}", line);
597	        } else {
598	            println!("{}", line);
599	        }
600	    }
601	
602	    fn finish_and_clear(&mut self) {}
603	
604	    fn output_mode(&self) -> OutputMode {
605	        self.mode
606	    }
607	
608	    fn step_indent(&self) -> usize {
609	        self.step_indent
610	    }
611	
612	    fn step_number(&self) -> &str {
613	        &self.step_number
614	    }
615	
616	    fn is_interactive(&self) -> bool {
617	        false
618	    }
619	
620	    fn live_output_callback(&mut self) -> Option<crate::shell::OutputCallback> {
621	        if matches!(self.mode, OutputMode::Verbose) {
622	            Some(Box::new(crate::ui::VerboseStreamSink::new(
623	                self.step_indent,
624	            )))
625	        } else {
626	            None
627	        }
628	    }
629	}
