25	/// Maximum total execution attempts per step (auto-retries + manual retries).
26	/// Prevents infinite loops when the recovery prompt always returns "retry"
27	/// (e.g., in test environments with MockUI).
28	const MAX_STEP_ATTEMPTS: u32 = 100;
29	
30	/// Result of executing a step with the retry/recovery loop.
31	pub(super) struct StepExecutionResult {
32	    /// The final step result.
33	    pub result: StepResult,
34	    /// Whether the user chose to skip in the recovery menu.
35	    pub skipped_by_user: bool,
36	    /// Whether the user chose to abort in the recovery menu.
37	    pub aborted: bool,
38	}
