281	/// Handle the interactive recovery menu after a step failure.
282	///
283	/// Sets `final_result` if the user chose to skip or abort. Returns `Ok(())`
284	/// to let the caller decide whether to continue or break the execution loop.
285	#[allow(clippy::too_many_arguments)]
286	fn handle_recovery_menu(
287	    step: &ResolvedStep,
288	    step_name: &str,
289	    step_indent: usize,
290	    result: StepResult,
291	    combined_output: &str,
292	    fix: Option<FixSuggestion>,
293	    hint: Option<String>,
294	    resolutions: &[diagnostic::ResolutionCandidate],
295	    diagnostic_funnel: bool,
296	    fix_history: &mut HashSet<String>,
297	    retry_count: &mut u32,
298	    skipped_by_user: &mut bool,
299	    aborted: &mut bool,
300	    final_result: &mut Option<StepResult>,
301	    project_root: &Path,
302	    base_env: &HashMap<String, String>,
303	    process_env: &HashMap<String, String>,
304	    ui: &mut dyn UserInterface,
305	    step_display: &mut dyn StepDisplay,
306	    event_bus: &mut EventBus,
307	) -> Result<()> {
308	    let pad = " ".repeat(step_indent);
309	    event_bus.emit(&BivvyEvent::RecoveryStarted {
310	        step: step_name.to_string(),
311	        error: combined_output.to_string(),
312	    });
313	    let has_hint = hint.is_some();
314	    loop {
315	        let action = if diagnostic_funnel {
316	            recovery::prompt_recovery_multi(ui, step_name, resolutions, fix_history, step_indent)?
317	        } else {
318	            recovery::prompt_recovery(
319	                ui,
320	                step_name,
321	                fix.as_ref(),
322	                has_hint,
323	                fix_history,
324	                step_indent,
325	            )?
326	        };
327	
328	        match action {
329	            RecoveryAction::Retry => {
330	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
331	                    step: step_name.to_string(),
332	                    action: "retry".to_string(),
333	                    command: None,
334	                });
335	                *retry_count += 1;
336	                return Ok(());
337	            }
338	            RecoveryAction::Fix(ref cmd) | RecoveryAction::CustomFix(ref cmd) => {
339	                let is_custom = matches!(action, RecoveryAction::CustomFix(_));
340	                let cmd = cmd.clone();
341	                if recovery::confirm_fix(ui, step_name, &cmd)? {
342	                    event_bus.emit(&BivvyEvent::RecoveryActionTaken {
343	                        step: step_name.to_string(),
344	                        action: if is_custom {
345	                            "custom_fix".to_string()
346	                        } else {
347	                            "fix".to_string()
348	                        },
349	                        command: Some(cmd.clone()),
350	                    });
351	                    let fix_ok = recovery::run_fix(&cmd, project_root, &step.env_vars.env)?;
352	                    fix_history.insert(cmd.clone());
353	                    if fix_ok {
354	                        step_display.message(&format!("{}Fix command succeeded.", pad));
355	                    } else {
356	                        step_display.message(&format!("{}Fix command failed.", pad));
357	                    }
358	                    *retry_count += 1;
359	                    return Ok(());
360	                }
361	                // User declined the fix — re-show recovery menu
362	            }
363	            RecoveryAction::Shell => {
364	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
365	                    step: step_name.to_string(),
366	                    action: "shell".to_string(),
367	                    command: None,
368	                });
369	                step_display.message(&format!(
370	                    "{}Dropping to debug shell (exit to return)...",
371	                    pad
372	                ));
373	                let debug_env =
374	                    crate::steps::build_step_env(step, project_root, base_env, process_env)?;
375	                crate::shell::debug::spawn_debug_shell(step_name, project_root, &debug_env)?;
376	                // After shell exit, re-show recovery menu
377	            }
378	            RecoveryAction::Skip => {
379	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
380	                    step: step_name.to_string(),
381	                    action: "skip".to_string(),
382	                    command: None,
383	                });
384	                *skipped_by_user = true;
385	                let mut r = result;
386	                r.recovery_detail = Some("skipped by user after failure".to_string());
387	                *final_result = Some(r);
388	                return Ok(());
389	            }
390	            RecoveryAction::Abort => {
391	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
392	                    step: step_name.to_string(),
393	                    action: "abort".to_string(),
394	                    command: None,
395	                });
396	                *aborted = true;
397	                let mut r = result;
398	                r.recovery_detail = Some("aborted by user".to_string());
399	                *final_result = Some(r);
400	                return Ok(());
401	            }
402	        }
403	    }
404	}
