406	/// Convert a config-level PromptConfig into a UI Prompt.
407	pub(super) fn config_prompt_to_ui_prompt(config: &crate::config::schema::PromptConfig) -> Prompt {
408	    use crate::config::schema::PromptType as ConfigPromptType;
409	
410	    let default = config.default.as_ref().and_then(|v| match v {
411	        serde_yaml::Value::String(s) => Some(s.clone()),
412	        serde_yaml::Value::Bool(b) => Some(b.to_string()),
413	        serde_yaml::Value::Number(n) => Some(n.to_string()),
414	        _ => None,
415	    });
416	
417	    let prompt_type = match &config.prompt_type {
418	        ConfigPromptType::Select => PromptType::Select {
419	            options: config
420	                .options
421	                .iter()
422	                .map(|o| PromptOption {
423	                    label: o.label.clone(),
424	                    value: o.value.clone(),
425	                })
426	                .collect(),
427	        },
428	        ConfigPromptType::Multiselect => PromptType::MultiSelect {
429	            options: config
430	                .options
431	                .iter()
432	                .map(|o| PromptOption {
433	                    label: o.label.clone(),
434	                    value: o.value.clone(),
435	                })
436	                .collect(),
437	        },
438	        ConfigPromptType::Confirm => PromptType::Confirm,
439	        ConfigPromptType::Input => PromptType::Input,
440	    };
441	
442	    Prompt {
443	        key: config.key.clone(),
444	        question: config.question.clone(),
445	        prompt_type,
446	        default,
447	    }
