64	/// Output methods for displaying messages, warnings, errors, and hints.
65	pub trait OutputWriter {
66	    /// Display a message to the user.
67	    fn message(&mut self, msg: &str);
68	
69	    /// Display a success message.
70	    fn success(&mut self, msg: &str);
71	
72	    /// Display a warning message.
73	    fn warning(&mut self, msg: &str);
74	
75	    /// Display an error message.
76	    fn error(&mut self, msg: &str);
77	
78	    /// Show a contextual hint to the user.
79	    fn show_hint(&mut self, hint: &str) {
80	        self.message(hint);
81	    }
82	
83	    /// Show a bordered error block with command, output, and optional hint.
84	    ///
85	    /// `indent` is the column at which the block should align (typically the
86	    /// step number width, so error content lines up under the step name).
87	    /// Implementations that don't render a visual box may ignore it.
88	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
89	        let _ = indent;
90	        self.error(command);
91	        if !output.is_empty() {
92	            self.message(output);
93	        }
94	        if let Some(h) = hint {
95	            self.show_hint(h);
96	        }
97	    }
98	}
