24	/// Check for an environment variable override for a prompt.
25	///
26	/// Users can skip any prompt by setting an env var matching the prompt key:
27	///   `BUMP=minor bivvy run --workflow release`
28	///
29	/// The lookup is case-insensitive on the key side: a prompt with key "bump"
30	/// matches env var `BUMP`, `bump`, or `Bump`.
31	pub(crate) fn env_override(prompt: &Prompt) -> Option<PromptResult> {
32	    let env_key = prompt.key.to_uppercase();
33	    let value = std::env::var(&env_key).ok()?;
34	
35	    let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
36	    if is_multiselect {
37	        let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
38	        Some(PromptResult::Strings(values))
39	    } else {
40	        Some(PromptResult::String(value))
41	    }
42	}
43	
44	/// Prompt the user for input.
45	///
46	/// Before showing any interactive prompt, checks for an environment variable
47	/// matching the prompt key (e.g., `BUMP=minor` for a prompt with key "bump").
48	/// This works in both interactive and non-interactive modes.
49	pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
50	    if let Some(result) = env_override(prompt) {
51	        return Ok(result);
52	    }
53	
54	    match &prompt.prompt_type {
55	        PromptType::Confirm => prompt_confirm(prompt, term),
56	        PromptType::Input => prompt_input(prompt, term),
57	        PromptType::Select { options } => prompt_select(prompt, options, term),
58	        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
59	    }
60	}
61	
62	fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
63	    let default = prompt
64	        .default
65	        .as_ref()
66	        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
67	        .unwrap_or(true);
68	
69	    let result = Confirm::new()
70	        .with_prompt(&prompt.question)
71	        .default(default)
72	        .interact_on(term)
73	        .map_err(map_dialoguer_err)?;
74	
75	    Ok(PromptResult::Bool(result))
76	}
77	
78	fn prompt_input(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
79	    let input = Input::<String>::new().with_prompt(&prompt.question);
80	
81	    let result: String = if let Some(default) = &prompt.default {
82	        input
83	            .default(default.clone())
84	            .interact_on(term)
85	            .map_err(map_dialoguer_err)?
86	    } else {
87	        input.interact_on(term).map_err(map_dialoguer_err)?
88	    };
89	
90	    Ok(PromptResult::String(result))
91	}
