111	    options.len() == 2
112	        && options.iter().any(|o| o.value == "yes")
113	        && options.iter().any(|o| o.value == "no")
114	}
115	
116	fn prompt_select(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
117	    // Use custom yes/no prompt for y/n keyboard shortcut support.
118	    // Requires a real TTY — prompt_yes_no uses term.read_key() directly.
119	    // On non-TTY, fall through to dialoguer's Select.
120	    //
121	    // Terminal foreground group is claimed in main.rs via tcsetpgrp(),
122	    // so read_key() works even when launched via `cargo run`.
123	    if is_yes_no(options) && term.is_term() {
124	        return prompt_yes_no(prompt, options, term);
125	    }
126	
127	    // Dumb terminals don't support cursor movement, so dialoguer's
128	    // clear-and-repaint cycles produce non-deterministic garbage.
129	    // Use a forward-only renderer instead.
130	    if super::is_dumb_term() && term.is_term() {
131	        return prompt_select_dumb(prompt, options, term);
132	    }
133	
134	    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
135	
136	    let default_idx = prompt
137	        .default
138	        .as_ref()
139	        .and_then(|d| options.iter().position(|o| o.value == *d))
140	        .unwrap_or(0);
141	
142	    let selection = Select::with_theme(&select_theme())
143	        .with_prompt(&prompt.question)
144	        .items(&labels)
145	        .default(default_idx)
146	        .interact_on(term)
147	        .map_err(map_dialoguer_err)?;
148	
149	    Ok(PromptResult::String(options[selection].value.clone()))
150	}
151	
152	/// Forward-only select prompt for dumb terminals.
153	///
154	/// Renders options once, accepts arrow keys and Enter without redrawing.
155	/// No cursor-movement sequences are emitted, so PTY output is deterministic.
156	fn prompt_select_dumb(
157	    prompt: &Prompt,
158	    options: &[PromptOption],
159	    term: &Term,
160	) -> Result<PromptResult> {
161	    let default_idx = prompt
162	        .default
163	        .as_ref()
164	        .and_then(|d| options.iter().position(|o| o.value == *d))
165	        .unwrap_or(0);
166	
167	    let mut sel = default_idx;
168	
169	    let _raw_guard = RawModeGuard::enter(term).map_err(BivvyError::Io)?;
170	
171	    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
172	
173	    for (i, opt) in options.iter().enumerate() {
174	        let line = if i == sel {
175	            format!("  › {}", opt.label)
176	        } else {
177	            format!("  · {}", opt.label)
178	        };
179	        term.write_line(&line).map_err(BivvyError::Io)?;
180	    }
181	    term.flush().map_err(BivvyError::Io)?;
182	
183	    loop {
184	        let key = term.read_key().map_err(BivvyError::Io)?;
185	
186	        match key {
187	            Key::Enter | Key::Char(' ') => {
188	                drop(_raw_guard);
189	                term.write_line(&format!("  › {}", options[sel].label))
190	                    .map_err(BivvyError::Io)?;
191	                return Ok(PromptResult::String(options[sel].value.clone()));
192	            }
193	            Key::ArrowDown | Key::Tab | Key::Char('j') => {
194	                sel = (sel + 1) % options.len();
195	            }
196	            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
197	                sel = (sel + options.len() - 1) % options.len();
198	            }
199	            _ => {}
200	        }

