13	/// A progress spinner for long-running operations.
14	pub struct ProgressSpinner {
15	    bar: ProgressBar,
16	    indent: usize,
17	}
18	
19	impl ProgressSpinner {
20	    /// Create a new spinner with a message.
21	    pub fn new(message: &str) -> Self {
22	        Self::with_indent(message, 0)
23	    }
24	
25	    /// Create a new spinner with indentation.
26	    pub fn with_indent(message: &str, indent: usize) -> Self {
27	        Self::create(message, indent, None)
28	    }
29	
30	    /// Create a new spinner inside a [`MultiProgress`].
31	    ///
32	    /// The spinner bar is inserted *before* the last bar (the pinned
33	    /// workflow progress bar), so it renders above it.
34	    pub fn with_multi(message: &str, indent: usize, multi: &MultiProgress) -> Self {
35	        Self::create(message, indent, Some(multi))
36	    }
37	
38	    fn create(message: &str, indent: usize, multi: Option<&MultiProgress>) -> Self {
39	        let raw_bar = ProgressBar::new_spinner();
40	        let prefix = " ".repeat(indent);
41	        raw_bar.set_style(
42	            ProgressStyle::default_spinner()
43	                .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
44	                .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
45	                .unwrap(),
46	        );
47	        raw_bar.set_message(message.to_string());
48	        raw_bar.enable_steady_tick(Duration::from_millis(80));
49	
50	        // If a multi-progress is provided, insert the spinner above the
51	        // last bar (the pinned workflow progress bar). `insert_from_back(1)`
52	        // puts it just before the final bar.
53	        let bar = if let Some(multi) = multi {
54	            multi.insert_from_back(1, raw_bar)
55	        } else {
56	            raw_bar
57	        };
58	
59	        Self { bar, indent }
60	    }
61	
62	    /// Create a spinner that doesn't show (for silent mode).
63	    pub fn hidden() -> Self {
64	        let bar = ProgressBar::hidden();
65	        Self { bar, indent: 0 }
66	    }
67	
68	    /// Get a clone of the inner progress bar for use in callbacks.
69	    ///
70	    /// This is useful for live output streaming: the cloned bar can be
71	    /// passed to a callback running on another thread, and `set_message`
72	    /// calls on it will update the spinner display in real-time.
73	    pub fn bar_clone(&self) -> ProgressBar {
74	        self.bar.clone()
75	    }
76	}
